mapper.update:
UPDATE customer_order SET status=#{status},payment_status=#{paymentStatus},internal_note=#{note},
  version=version+1,updated_at=UTC_TIMESTAMP(3)
WHERE id=#{id} AND version=#{version}

mapper.select:
SELECT p.*,o.order_number,o.customer_name,o.email FROM payment_record p
JOIN customer_order o ON o.id=p.order_id 
ORDER BY p.created_at DESC,p.id DESC LIMIT #{limit} OFFSET #{offset}
